inline void generate_cwru_window(float* buffer, int fault_class) {
    static int win_idx[NUM_SIM_CLASSES] = {0};
    int w = win_idx[fault_class];
    for (int i = 0; i < WINDOW_SIZE; i++)
        buffer[i] = pgm_read_float(&CWRU_WINDOWS[fault_class][w][i]);
    win_idx[fault_class] = (w + 1) % WINDOWS_PER_CLASS;
}
